s = input().strip()
vowels = set(['A', 'E', 'I', 'O', 'U'])
vscore = 0
cscore = 0
for i in range(len(s)):
	score = len(s) - i
	if s[i] in vowels:
		vscore += score
	else:
		cscore += score
if cscore > vscore:
	print('Stuart', cscore)
elif vscore > cscore:
	print('Kevin', vscore)
else:
	print('Draw')
